1013			t.Fatalf("原有房间被改写或重新排序：\n得到: %v\n期望: %v", rooms[:2], want)
1014		}
1015		for i, created := range createdRooms {
1016			if !reflect.DeepEqual(rooms[2+i], created) {
1017				t.Fatalf("列表第 %d 条新记录与创建响应不一致：\n列表: %v\n响应: %v", i+1, rooms[2+i], created)
1018			}
1019		}
1020	
1021		// 本地保存记录：与列表一致，且每个新房间的 turnSeconds 字段都明确存在、
1022		// 数值等于提交值——0 也必须落盘为 0，不能缺省或被改成默认时间。
1023		saved := decodeRecords(t, readDataFile(t, dataDir))
1024		if !reflect.DeepEqual(saved, rooms) {
1025			t.Fatalf("本地保存记录与房间列表不一致：\n文件: %v\n列表: %v", saved, rooms)
1026		}
1027		for i, tc := range cases {
1028			record, ok := saved[2+i].(map[string]any)
1029			if !ok {
1030				t.Fatalf("保存的第 %d 条新记录不是对象: %v", i+1, saved[2+i])
1031			}
1032			got, present := record["turnSeconds"]
1033			if !present {
1034				t.Fatalf("%s turnSeconds=%d 的保存记录缺少 turnSeconds 字段（0 也必须明确保存）", tc.game, tc.turn)
1035			}
1036			if got != float64(tc.turn) {
1037				t.Fatalf("保存的每步时间 = %v，期望 %d", got, tc.turn)
1038			}
1039		}
1040	}
1041	
1042	// 每步时间以非整数形式提供时必须拒绝：null、字符串、布尔值、对象、数组，
1043	// 以及带小数点的 30.0（数值虽为整数）和科学计数法 3e1，都按非整数写法拒绝，
1044	// 不能取整或转换后创建。返回 400 且 error 说明 turnSeconds 必须是整数，
1045	// 而不是缺少字段；不返回成功房间，已有记录与本地文件保持原样。
1046	// 请求中的名称、规则和人数均合法，失败原因只能落在时间配置上。
1047	func TestCreateRoomRejectsNonIntegerTurnSeconds(t *testing.T) {
1048		dataDir := t.TempDir()
1049		seed := seedRooms(t, dataDir, seedRecord1, seedRecord2)
1050		baseURL := startServer(t, dataDir)
1051	
1052		cases := []struct {
1053			desc string
1054			body string
1055		}{
1056			{"时间为 null", `{"name":"null 时间房","game":"gomoku","capacity":2,"turnSeconds":null}`},
1057			{"时间为字符串", `{"name":"字符串时间房","game":"gomoku","capacity":2,"turnSeconds":"30"}`},
1058			{"时间为布尔值", `{"name":"布尔时间房","game":"ludo","capacity":3,"turnSeconds":true}`},
1059			{"时间为对象", `{"name":"对象时间房","game":"ludo","capacity":4,"turnSeconds":{"seconds":30}}`},
1060			{"时间为数组", `{"name":"数组时间房","game":"gomoku","capacity":2,"turnSeconds":[30]}`},
1061			{"时间为带小数点的整数值 30.0", `{"name":"小数点时间房","game":"gomoku","capacity":2,"turnSeconds":30.0}`},
1062			{"时间为科学计数法 3e1", `{"name":"科学计数时间房","game":"ludo","capacity":2,"turnSeconds":3e1}`},
1063		}
1064	
1065		for _, tc := range cases {
1066			status, rejected := postRoom(t, baseURL, tc.body)
1067			if status != http.StatusBadRequest {
1068				t.Fatalf("%s：状态码 = %d，期望 400，响应: %v", tc.desc, status, rejected)
1069			}
1070			errMsg, _ := rejected["error"].(string)
1071			if !strings.Contains(errMsg, "turnSeconds") || !strings.Contains(errMsg, "整数") {
1072				t.Fatalf("%s：error 应说明 turnSeconds 必须是整数，实际: %q", tc.desc, errMsg)
1073			}
1074			if strings.Contains(errMsg, "缺少") {
1075				t.Fatalf("%s：字段已提供但类型不符，error 不应说成缺少字段，实际: %q", tc.desc, errMsg)
1076			}
1077			// 名称、规则与人数均合法，错误原因只能落在时间字段上。
1078			if strings.Contains(errMsg, "名称") || strings.Contains(errMsg, "capacity") || strings.Contains(errMsg, "game") {
1079				t.Fatalf("%s：其余配置均合法，error 不应落在无关字段上，实际: %q", tc.desc, errMsg)
1080			}
1081			if _, ok := rejected["id"]; ok {
1082				t.Fatalf("%s：被拒绝的请求不应返回房间编号，实际: %v", tc.desc, rejected)
1083			}
1084		}
1085	
1086		// 缺少字段与类型不符要能区分：未提供 turnSeconds 报“缺少必填字段”，不含“整数”。
1087		missingStatus, missingBody := postRoom(t, baseURL, `{"name":"复验缺时间","game":"gomoku","capacity":2}`)
1088		if missingStatus != http.StatusBadRequest {
1089			t.Fatalf("缺时间复验状态码 = %d，期望 400，响应: %v", missingStatus, missingBody)
1090		}
1091		missingErr, _ := missingBody["error"].(string)
1092		if !strings.Contains(missingErr, "缺少必填字段") || !strings.Contains(missingErr, "turnSeconds") {
1093			t.Fatalf("缺少 turnSeconds 应报“缺少必填字段：turnSeconds”，实际: %q", missingErr)
1094		}
1095		if strings.Contains(missingErr, "整数") {
1096			t.Fatalf("缺少时间字段不应报“必须是整数”，实际: %q", missingErr)
1097		}
1098	
1099		// 全部拒绝后：已有房间数量、次序、内容与附带字段不变，本地文件逐字节保留。
1100		assertRoomsUnchanged(t, baseURL, dataDir, seed)
1101	}
1102	
1103	// 整数但越界的每步时间必须拒绝：-1、1、9 和 601 属于范围错误，
1104	// 返回 400（不是 500 服务内部故障），error 说明允许 0（不限时）或 10 至 600 秒；
1105	// 不返回成功房间，已有记录与本地文件保持原样。只把时间改为合法整数、
1106	// 保留其余配置再提交时应正常创建，新房间按修正后的秒数追加，被拒的时间不留记录。
1107	func TestCreateRoomRejectsOutOfRangeTurnSeconds(t *testing.T) {
1108		dataDir := t.TempDir()
1109		seed := seedRooms(t, dataDir, seedRecord1, seedRecord2)
1110		baseURL := startServer(t, dataDir)
1111	
1112		outOfRange := []int{-1, 1, 9, 601}
1113		for _, turn := range outOfRange {
1114			body, _ := json.Marshal(map[string]any{
1115				"name": "越界时间房", "game": "ludo", "capacity": 3, "turnSeconds": turn,
1116			})
1117			status, rejected := postRoom(t, baseURL, string(body))
1118			if status != http.StatusBadRequest {
1119				t.Fatalf("turnSeconds=%d：状态码 = %d，期望 400（不得返回成功或 500），响应: %v", turn, status, rejected)
1120			}
1121			errMsg, _ := rejected["error"].(string)
1122			for _, part := range []string{"0", "10", "600"} {
1123				if !strings.Contains(errMsg, part) {
1124					t.Fatalf("turnSeconds=%d：error 应包含 %q 以说明允许 0 或 10 至 600 秒，实际: %q", turn, part, errMsg)
1125				}
1126			}
1127			// 名称、规则与人数均合法，错误原因只能落在时间范围上。
1128			if strings.Contains(errMsg, "名称") || strings.Contains(errMsg, "capacity") {
1129				t.Fatalf("turnSeconds=%d：其余配置均合法，error 不应落在无关字段上，实际: %q", turn, errMsg)
1130			}
1131			if _, ok := rejected["id"]; ok {
1132				t.Fatalf("turnSeconds=%d：被拒绝的请求不应返回房间编号，实际: %v", turn, rejected)
1133			}
1134		}
1135	
1136		// 全部拒绝后：已有房间数量、次序、内容与附带字段不变，本地文件逐字节保留。
1137		assertRoomsUnchanged(t, baseURL, dataDir, seed)
1138	
1139		// 只把时间改成合法整数、其余配置原样保留再提交，应正常创建。
1140		const fixedTurn = 30
1141		body, _ := json.Marshal(map[string]any{
1142			"name": "越界时间房", "game": "ludo", "capacity": 3, "turnSeconds": fixedTurn,
1143		})
1144		status, created := postRoom(t, baseURL, string(body))
1145		if status != http.StatusCreated {
1146			t.Fatalf("修正时间后创建状态码 = %d，期望 201，响应: %v", status, created)
1147		}
1148		if got := created["turnSeconds"]; got != float64(fixedTurn) {
1149			t.Fatalf("修正后保存的每步时间 = %v，期望 %d", got, fixedTurn)
1150		}
1151		if got := created["name"]; got != "越界时间房" {
1152			t.Fatalf("修正后名称 = %v，期望沿用原名称", got)
1153		}
1154		if got := created["game"]; got != "ludo" {
1155			t.Fatalf("修正后规则 = %v，期望沿用 ludo", got)
1156		}
1157		if got := created["capacity"]; got != float64(3) {
1158			t.Fatalf("修正后人数 = %v，期望沿用 3", got)
1159		}
1160	
1161		// 新房间按修正后的秒数追加在最后；曾被拒的时间不留下任何记录。
1162		_, rooms := getRooms(t, baseURL)
1163		if len(rooms) != 3 {
1164			t.Fatalf("房间数量 = %d，期望 3（种子 2 条 + 修正后 1 条，被拒时间不得留记录）", len(rooms))
1165		}
1166		if want := decodeRecords(t, seed); !reflect.DeepEqual(rooms[:2], want) {
1167			t.Fatalf("原有房间被改动：\n得到: %v\n期望: %v", rooms[:2], want)
1168		}
1169		last, ok := rooms[2].(map[string]any)
1170		if !ok {
1171			t.Fatalf("新记录不是对象: %v", rooms[2])
1172		}
1173		if !reflect.DeepEqual(last, created) {
1174			t.Fatalf("列表中的新记录与创建响应不一致：\n列表: %v\n响应: %v", last, created)
1175		}
1176		for _, record := range rooms {
1177			room, _ := record.(map[string]any)
1178			if room["name"] == "越界时间房" {
1179				if got := room["turnSeconds"]; got != float64(fixedTurn) {
1180					t.Fatalf("列表中出现曾被拒绝的时间 %v，说明越界值被保存或留了记录", got)
1181				}
1182			}
1183		}
1184	}
1185	
1186	// 只含会被去掉的首尾空白（含 U+0085、U+00A0）的名称视为空，
1187	// 返回 400 并说明名称不能为空，不返回新房间编号，已有数据保持不变。
1188	func TestCreateRoomRejectedWhenNameOnlyWhitespace(t *testing.T) {
1189		dataDir := t.TempDir()
1190		seed := seedRooms(t, dataDir, seedRecord1, seedRecord2)
1191		baseURL := startServer(t, dataDir)
1192	
1193		body, _ := json.Marshal(map[string]any{"name": "  \u00a0 \u0085  ", "game": "gomoku", "capacity": 2, "turnSeconds": 0})
1194		status, rejected := postRoom(t, baseURL, string(body))
1195		if status != http.StatusBadRequest {
1196			t.Fatalf("状态码 = %d，期望 400，响应: %v", status, rejected)
1197		}
1198		errMsg, _ := rejected["error"].(string)
1199		if !strings.Contains(errMsg, "不能为空") {
1200			t.Fatalf("error 应说明名称不能为空，实际: %q", errMsg)
1201		}
1202		if _, ok := rejected["id"]; ok {
1203			t.Fatalf("被拒绝的请求不应返回房间编号，实际: %v", rejected)
1204		}
1205	
1206		assertRoomsUnchanged(t, baseURL, dataDir, seed)
1207	}
