// 数据可读、配置合法但保存无法完成时，应返回 500 并说明保存失败，
// 原有数据保持完整可读，不出现只保存了一部分的新记录。
func TestCreateRoomFailsWhenSaveFails(t *testing.T) {
	dataDir := t.TempDir()
